pragma solidity ^0.8.20;

import "forge-std/Test.sol";

contract Caller {
    uint256 public counter;

    function callAddress(address a) external {
        uint8 _step = 0;
        bool _continue = true;
        while (_continue) {
            if (_step == 0) {
                if (a != address(0)) {
                    _step = 1;
                } else {
                    _step = 1;
                }
            } else if (_step == 1) {
                unchecked {
                    // unchecked low-level call vulnerability: ignoring return value
                    a.call{gas: gasleft()}("");
                }
                _step = 2;
            } else if (_step == 2) {
                _continue = false;
            }
        }
        // Increase counter to prove function completed despite revert in call
        counter++;
    }
}

contract Rejecter {
    fallback() external payable {
        revert("Rejecter fallback reverts");
    }
}

contract ExploitTest is Test {
    Caller caller;
    Rejecter rejecter;

    function setUp() public {
        caller = new Caller();
        rejecter = new Rejecter();
    }

    function test_exploit_unchecked_low_level_calls() public {
        // Call Caller.callAddress with Rejecter's address, which reverts on fallback
        // The low-level call inside Caller ignores the revert and does not bubble it up
        caller.callAddress(address(rejecter));

        // Assert the outer call succeeded despite internal revert => exploit succeeded
        assertEq(caller.counter(), 1, "Outer call succeeded despite inner revert");

        // Additional sanity: calling with address(0) should also succeed
        caller.callAddress(address(0));
        assertEq(caller.counter(), 2, "Call with address(0) succeeded");
    }
}

