// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";

contract UncheckedLowLevelCalls {
    event CallSucceeded(address target);
    event CallFailed(address target);

    // Vulnerable function: calls to external address via low-level call, does not check success
    function callTo(address target) external {
        // Call the target with empty calldata
        (bool success, ) = target.call("");
        // Unchecked low-level call, success not verified
        if (success) {
            emit CallSucceeded(target);
        } else {
            emit CallFailed(target);
        }
    }
}

contract Rejecter {
    fallback() external payable {
        revert("Rejecter fallback revert");
    }
}

contract UncheckedLowLevelCallsExploitTest is Test {
    UncheckedLowLevelCalls public vulnerable;
    Rejecter public rejecter;

    function setUp() public {
        vulnerable = new UncheckedLowLevelCalls();
        rejecter = new Rejecter();
    }

    function test_exploit_unchecked_low_level_calls() public {
        // Call vulnerable contract's callTo() with Rejecter address,
        // which reverts on fallback, but vulnerable contract ignores failure.
        vm.expectEmit(true, true, false, false);
        emit CallFailed(address(rejecter));
        vulnerable.callTo(address(rejecter));

        // The outer call should succeed despite inner revert
        assertTrue(address(vulnerable) != address(0), "Vulnerable contract deployed");
        assertTrue(address(rejecter) != address(0), "Rejecter contract deployed");

        // We expect the outer tx to succeed despite inner revert
        // So calling callTo should not revert
        // We also capture emitted events to confirm the revert happened internally

        // Additional sanity check: callTo returns nothing and does not revert
        // So we can call it again safely
        vulnerable.callTo(address(rejecter));

        // The test passes if no revert happened
        assertTrue(true, "Outer call succeeded despite inner revert");
    }

    event CallFailed(address target);
}
